// ---- Vapi tool-call parsing (defensive) --------------------------------
// Vapi POSTs { message: { type:'tool-calls', toolCallList:[{id,name,arguments}], call:{...} } }
// n8n nests the HTTP body under $json.body. `arguments` sometimes arrives as a
// JSON *string* rather than an object, so parse it defensively.
function parseVapi(item) {
  const body = item.body || item;
  const msg = body.message || {};
  const list = msg.toolCallList || msg.toolCalls || [];
  const tc = list[0] || {};
  let args = tc.arguments ?? tc.function?.arguments ?? {};
  if (typeof args === 'string') { try { args = JSON.parse(args); } catch (e) { args = {}; } }
  const callerNumber = msg.call?.customer?.number || null;
  return {
    toolCallId: tc.id || tc.toolCallId || 'unknown',
    name: tc.name || tc.function?.name || '',
    args: args || {},
    callerNumber,
    callId: msg.call?.id || null,
  };
}

// ---- Phone normalisation (mirrors lib/squeegee/sms.ts) -----------------
function normalizePhone(raw) {
  const digits = String(raw ?? '').replace(/[^0-9]/g, '');
  const ten = digits.length === 11 && digits.startsWith('1') ? digits.slice(1) : digits;
  if (ten.length !== 10) return null;
  return { phone10: ten, e164: '+1' + ten };
}

// ---- Spoken-form money -------------------------------------------------
// TTS reads "$475" inconsistently; spelling it out is the documented fix.
const ONES = ['zero','one','two','three','four','five','six','seven','eight','nine','ten',
  'eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen'];
const TENS = ['','','twenty','thirty','forty','fifty','sixty','seventy','eighty','ninety'];
function under1000(n) {
  let out = [];
  if (n >= 100) { out.push(ONES[Math.floor(n / 100)] + ' hundred'); n %= 100; }
  if (n >= 20) { out.push(TENS[Math.floor(n / 10)] + (n % 10 ? '-' + ONES[n % 10] : '')); }
  else if (n > 0) { out.push(ONES[n]); }
  return out.join(' ');
}
function spellDollars(amount) {
  const n = Math.round(Number(amount) || 0);
  if (n === 0) return 'zero dollars';
  const th = Math.floor(n / 1000), rest = n % 1000;
  let s = '';
  if (th) s += under1000(th) + ' thousand' + (rest ? ' ' : '');
  if (rest) s += under1000(rest);
  return s + ' dollars';
}

// ---- Spoken-form date/time (America/New_York) --------------------------
function spokenSlot(iso) {
  const d = new Date(iso);
  const day = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', weekday: 'long', month: 'long', day: 'numeric' }).format(d);
  const hourFmt = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: 'numeric', minute: '2-digit', hour12: true }).format(d);
  let [clock, ampm] = hourFmt.split(' ');
  let [h, m] = clock.split(':');
  const timePart = m === '00' ? h : h + ' ' + m;
  const hh = Number(h);
  // 12 PM..4:59 PM = afternoon, 5 PM+ = evening (noon used to fall into 'evening').
  const partOfDay = ampm === 'AM' ? 'in the morning' : ((hh === 12 || hh < 5) ? 'in the afternoon' : 'in the evening');
  return day + ' at ' + timePart + ' ' + partOfDay;
}

// ---- DST-correct Eastern ISO (mirrors lib/squeegee/calcom.ts) ----------
function easternOffsetFor(dateStr) {
  try {
    const dt = new Date(dateStr + 'T12:00:00Z');
    const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', timeZoneName: 'longOffset' }).formatToParts(dt);
    const tz = parts.find(p => p.type === 'timeZoneName')?.value;
    const m = tz && tz.match(/GMT([+-]\d{2}:\d{2})/);
    return m ? m[1] : '-05:00';
  } catch (e) { return '-05:00'; }
}

// ---- Always-200 Vapi envelope -----------------------------------------
function vapiResult(toolCallId, text) {
  return [{ json: { results: [{ toolCallId, result: text }] } }];
}

// ---------------------------------------------------------------------------
// SOURCE OF TRUTH: dr-squeegee/lib/squeegee/pricing.ts — mirrored, re-sync on change.
// Verified against the repo 2026-08-28.
// CONTRACT: matches the `quote_service` tool schema in vapi/tools.json.
//   serviceType?  window_cleaning | house_wash | driveway | surface_cleaning |
//                 pool_deck | pavers | gutter_cleaning | roof_soft_wash
//   windowCounts? { story1: n, story2: n, story3: n }  (legacy "1"/"2"/"3" keys also accepted)
//   coverage? exterior|both
//   sqft? number  sqftService? Driveway|Surface Cleaning|Pool Deck|Pavers
//   houseWashTier? one of the five tier keys
// Service is inferred from whichever fields are present, so the model can omit
// serviceType and still get a correct answer.
// ---------------------------------------------------------------------------
const WINDOW_PRICING = {
  base: 7, storyMult: { 1: 1, 2: 1.3, 3: 1.7 },
  coverageMult: { exterior: 1, both: 1.8 }, minJob: 200, roundTo: 5,
};
const SQFT_SERVICE_DEFAULTS = { 'Driveway': 0.20, 'Surface Cleaning': 0.18, 'Pool Deck': 0.22, 'Pavers': 0.25 };
const SQFT_ALIAS = { driveway: 'Driveway', surface_cleaning: 'Surface Cleaning',
                     pool_deck: 'Pool Deck', pavers: 'Pavers' };
const HOUSE_WASH_TIERS = {
  '1-story-standard': { label: '1-story, up to 1,500 square feet', price: 300 },
  '1-story-large':    { label: '1-story, large',                   price: 350 },
  '2-story-standard': { label: '2-story, up to 2,500 square feet', price: 400 },
  '2-story-large':    { label: '2-story, large',                   price: 475 },
  '3-story':          { label: '3-story',                          price: 550 },
};
const ONSITE_ONLY = new Set(['gutter_cleaning', 'roof_soft_wash']);

function computeWindowPriceMulti(counts, coverage) {
  const cov = WINDOW_PRICING.coverageMult[coverage] ?? 1;
  let subtotal = 0, count = 0;
  for (const s of [1, 2, 3]) {
    const c = Number(counts?.['story' + s] ?? counts?.[s] ?? counts?.[String(s)] ?? 0);
    if (c > 0) { count += c; subtotal += c * WINDOW_PRICING.base * WINDOW_PRICING.storyMult[s]; }
  }
  if (count <= 0) return { price: 0, count: 0 };
  const raw = subtotal * cov;
  const rounded = Math.round(raw / WINDOW_PRICING.roundTo) * WINDOW_PRICING.roundTo;
  return { price: Math.max(WINDOW_PRICING.minJob, rounded), count };  // min + rounding applied ONCE
}

function priceOne(s) {
  const type = String(s.serviceType || '').toLowerCase().trim();
  if (ONSITE_ONLY.has(type)) return { onsite: type.replace(/_/g, ' ') };

  const counts = s.windowCounts || (type === 'window_cleaning' ? {} : null);
  const hasWindows = counts && [1, 2, 3].some(k => Number(counts['story' + k] ?? counts[k] ?? counts[String(k)] ?? 0) > 0);
  if (hasWindows) {
    const coverage = s.coverage === 'both' ? 'both' : 'exterior';
    const r = computeWindowPriceMulti(counts, coverage);
    return { price: r.price, line: r.count + ' window' + (r.count === 1 ? '' : 's') + ', ' +
      (coverage === 'both' ? 'inside and out' : 'exterior only') + ', ' + spellDollars(r.price) };
  }

  if (s.houseWashTier) {
    const tier = HOUSE_WASH_TIERS[s.houseWashTier];
    if (tier) return { price: tier.price, line: 'house wash, ' + tier.label + ', ' + spellDollars(tier.price) };
    return { missing: 'house wash (need the story count and rough size)' };
  }
  if (type === 'house_wash') return { missing: 'house wash (need the story count and rough size)' };

  const key = s.sqftService || SQFT_ALIAS[type];
  const sqft = Number(s.sqft || 0);
  if (key && SQFT_SERVICE_DEFAULTS[key] != null) {
    if (sqft > 0) {
      const price = Math.round(sqft * SQFT_SERVICE_DEFAULTS[key]);
      return { price, line: key.toLowerCase() + ', ' + sqft + ' square feet, ' + spellDollars(price) };
    }
    return { missing: key.toLowerCase() + ' (need the rough square footage)' };
  }
  if (type === 'window_cleaning') return { missing: 'window cleaning (need the number of windows per floor)' };
  return { missing: null };
}

const v = parseVapi($input.first().json);
const a = v.args || {};
const services = Array.isArray(a.services) && a.services.length ? a.services : [a];

let total = 0;
const lines = [], onsite = [], missing = [];
for (const s of services) {
  const r = priceOne(s || {});
  if (r.onsite) { onsite.push(r.onsite); continue; }
  if (r.missing !== undefined && r.price === undefined) { if (r.missing) missing.push(r.missing); continue; }
  total += r.price; lines.push(r.line);
}

let text;
if (lines.length === 0 && onsite.length > 0) {
  text = 'No set price for ' + onsite.join(' and ') + '. Tell the caller that one needs a quick look in person ' +
         'and that Anthony confirms the number before any work happens. Do not say a figure.';
} else if (lines.length === 0 && missing.length > 0) {
  text = 'Not enough detail yet for ' + missing.join(' and ') + '. Ask for that, then call this again.';
} else if (lines.length === 0) {
  text = 'Not enough detail to price anything yet. Ask which service they want and the size or window count.';
} else {
  text = 'Estimate: ' + spellDollars(total) + ' total. Breakdown: ' + lines.join('; ') + '.';
  if (onsite.length) text += ' They also asked about ' + onsite.join(' and ') +
      ' — on-site quote only, so do not say a figure for that.';
  if (missing.length) text += ' Still missing detail for ' + missing.join(' and ') + '.';
  text += ' Say this is an estimate from what they described, confirmed on site.';
}
return vapiResult(v.toolCallId, text);
